from pathlib import Path
base=Path(__file__).parent
source=(base/'prepare-d04-combat-cloud-r1.py').read_text(encoding='utf-8').replace('d04-combat-measure','d04-physical-flow').replace('d04-combat','d04-physical')
methods=['FantasyCard.Server.Tests.Persistence.PostgresPhysicalEquipmentTelemetryTests.RealCraftReforgeMarketAndDiscardCountOneMintAndDestroyWhileOriginalCreatorSurvivesOwnerAndSourceChanges','FantasyCard.Server.Tests.Persistence.PostgresPhysicalEquipmentTelemetryTests.CommittedRecyclingUsesItsExactOriginalHoldAndReceiptWhileOtherItemCannotBorrowItsBuild','FantasyCard.Server.Tests.Persistence.PostgresPhysicalEquipmentTelemetryTests.UnknownTerminalTimeAndDuplicateDestructionClaimsRemainCoverageGapsRatherThanNewSupply','FantasyCard.Server.Tests.Persistence.PostgresPhysicalEquipmentTelemetryTests.ArchiveMarkersCoverWalletRecipeWishAndLoadoutsWithoutBackdatingLateCreditAmounts','FantasyCard.Server.Tests.Persistence.PostgresPhysicalEquipmentTelemetryTests.RealPreparationCancelAndMatchAdmissionRetainSelfOwnershipLegsWithoutChangingGameRules','FantasyCard.Server.Tests.EndToEnd.ProcessLifecycleRecoveryTests.Full_host_admin_economy_report_keeps_existing_HTTPS_key_and_no_store_boundary']
lines=source.splitlines();at=[i for i,line in enumerate(lines) if line.startswith('new=')];assert len(at)==1;lines[at[0]]='new='+repr(methods);source='\n'.join(lines)+'\n'
needle="source=source.replace(needle,','.join(\"'-method',\"+repr(x) for x in new))";assert source.count(needle)==1
source=source.replace(needle,needle+".replace('planned_report_cases=4','planned_report_cases=6')").replace("'planned_report_cases':4","'planned_report_cases':6").replace('dict(cases=4,','dict(cases=6,')
target=base/'prepare-d04-physical-cloud-r1.py';assert not target.exists();compile(source,str(target),'exec');target.write_text(source,encoding='utf-8')
target=base/'verify-d04-physical-cache-before-r1.py';assert not target.exists();text=(base/'verify-d04-combat-cache-before-r1.py').read_text(encoding='utf-8').replace('d04-combat-cache','d04-physical-cache');target.write_text(text,encoding='utf-8')
print('Prepared6 isolated physical-ledger/archive/admission/admin scenarios with verified dependency cache reuse.')
